{
  "story": "Scores measure token affinities. Softmax turns raw scores into probabilities. Sampling or argmax picks the next word.",
  "aha": {
    "stateId": "step_softmax",
    "observation": "Softmax forces all token scores to sum to one, turning them into clear probabilities."
  },
  "layout": {
    "preset": "card",
    "width": 640
  },
  "parts": [
    {
      "id": "rail",
      "kind": "step-rail",
      "bind": {
        "active": "inputs.stepIndex",
        "items": "variant.states"
      }
    },
    {
      "id": "pic",
      "kind": "fixed-picture",
      "bind": {
        "active": "state.active",
        "regions": "variant.regions",
        "completedBefore": "state.active"
      }
    },
    {
      "id": "callout",
      "kind": "active-callout",
      "bind": {
        "reason": "state.why",
        "target": "state.calloutRegion",
        "text": "state.sentence"
      }
    },
    {
      "id": "readouts",
      "kind": "value-readout",
      "bind": {
        "values": "state.readouts"
      }
    }
  ],
  "controls": [
    {
      "id": "stepIndex",
      "kind": "index",
      "label": "Step",
      "options": ["Scores", "Softmax", "Selection"]
    },
    {
      "id": "resetBtn",
      "kind": "reset",
      "label": "Reset",
      "options": []
    }
  ],
  "data": {
    "variants": [
      {
        "label": "Transformer Next-Word Pipeline",
        "regions": [
          {
            "id": "reg_scores",
            "label": "Raw Scores",
            "values": ["12.5", "3.1", "1.0"]
          },
          {
            "id": "reg_probs",
            "label": "Probabilities",
            "values": ["0.92", "0.06", "0.02"]
          },
          {
            "id": "reg_token",
            "label": "Selected Token",
            "values": ["the"]
          }
        ],
        "states": [
          {
            "id": "step_scores",
            "label": "1. Scores",
            "sentence": "Attention outputs raw logits for every possible vocabulary token.",
            "why": "Higher score means higher initial affinity.",
            "active": ["reg_scores"],
            "calloutRegion": "reg_scores",
            "readouts": [
              {
                "id": "r1",
                "label": "Top Logit",
                "value": "12.5"
              }
            ]
          },
          {
            "id": "step_softmax",
            "label": "2. Softmax",
            "sentence": "Exponentiation and normalization turn logits into a probability distribution.",
            "why": "Probabilities sum to exactly 1.0.",
            "active": ["reg_probs"],
            "calloutRegion": "reg_probs",
            "readouts": [
              {
                "id": "r2",
                "label": "Sum",
                "value": "1.00"
              }
            ]
          },
          {
            "id": "step_select",
            "label": "3. Selection",
            "sentence": "Argmax or sampling picks the definitive next token from the distribution.",
            "why": "The highest probability token is generated.",
            "active": ["reg_token"],
            "calloutRegion": "reg_token",
            "readouts": [
              {
                "id": "r3",
                "label": "Chosen",
                "value": "the"
              }
            ]
          }
        ]
      }
    ]
  }
}
